def garantir_leitura_livre(raiz: Path) -> None:
    """Tira do settings.json do Claude os deny de leitura que a camada instalava.

    Decisão do dono (17/08/2026, regra 8): ler credencial localmente é livre —
    quem barra o que sobe é o professor (orientar-credencial.py), e muro de
    leitura só fica onde não há professor (Devin). Sai só a linha EXATA que a
    camada instalava; regra parecida escrita pela casa é da casa e fica.
    """
    destino = raiz / ".claude/settings.json"
    if not destino.exists():
        return
    cfg = json.loads(destino.read_text(encoding="utf-8"))
    deny = cfg.get("permissions", {}).get("deny", [])
    tirados = [d for d in deny if d in DENYS_APOSENTADOS]
    if not tirados:
        print("  em dia:  leitura livre (nenhum deny aposentado no settings.json)")
        return
    deny[:] = [d for d in deny if d not in DENYS_APOSENTADOS]
    destino.write_text(json.dumps(cfg, indent=2, ensure_ascii=False) + "\n",
                       encoding="utf-8", newline="\n")
    print(f"  removido: deny de leitura aposentado ({', '.join(tirados)}) "
          "— regra 8: ler é livre")


